// === Tab: mySketch ===
var nmobiles = 6000; // 适中的粒子数量
var mobiles = [];
var noisescale;
var a1, a2, a3, a4, a5, amax;
var shoreLine; // 单一岸边界限
var triggerZones = []; // 触发区域
var activeTriggers = []; // 当前激活的触发
var lastTriggerTime = 0; // 上次触发时间
var triggerCooldown = 500; // 触发冷却时间(毫秒)

// 十种柔和的颜色 (降低饱和度，提高美感)
var colors = [
  [0, 60, 90],     // 柔红色
  [30, 60, 90],    // 柔橙色
  [60, 60, 90],    // 柔黄色
  [120, 60, 90],   // 柔绿色
  [180, 60, 90],   // 柔青色
  [210, 60, 90],   // 柔蓝色
  [240, 60, 90],   // 柔深蓝
  [270, 60, 90],   // 柔紫色
  [300, 60, 90],   // 柔粉色
  [330, 60, 90]    // 柔玫红
];

function setup() {
  createCanvas(1000, 700);
  background(0);
  noFill();  
  colorMode(HSB, 360, 255, 255, 255);
  strokeWeight(1.2); // 适中的线条粗细

  // 初始化单一岸边界限 - 位于画布右侧
  shoreLine = width * 0.85;

  // 初始化触发区域 - 将岸边区域分成10个垂直区域
  var zoneHeight = height / 10;
  for (var i = 0; i < 10; i++) {
    triggerZones.push({
      y: i * zoneHeight,
      height: zoneHeight,
      color: colors[i],
      active: false,
      activeSince: 0,
      duration: 0
    });
  }

  reset();
}

function reset() {
  noisescale = random(1.2, 2.0); // 适中的噪声强度
  noiseDetail(int(random(2, 4)));
  amax = random(6, 10); // 适中的最大振幅
  a1 = random(1, amax);
  a2 = random(1, amax);
  a3 = random(1, amax);
  a4 = random(1, amax);
  a5 = 12; // 适中的速度

  mobiles = [];
  for (var i = 0; i < nmobiles; i++) {
    mobiles[i] = new Mobile(i);
  }

  // 重置激活状态
  activeTriggers = [];
  lastTriggerTime = 0;
}

function draw() {
  // 使用很淡的半透明背景创造柔和的拖尾效果
  fill(0, 8);
  noStroke();
  rect(0, 0, width, height);

  // 绘制岸边界限
  drawShoreLine();

  // 绘制触发区域指示器
  drawTriggerZones();

  // 更新和显示所有粒子
  for (var i = 0; i < mobiles.length; i++) {
    mobiles[i].run();
  }

  // 更新激活的触发效果
  updateActiveTriggers();
}

function drawShoreLine() {
  // 绘制柔和的岸边界限
  stroke(255, 120);
  strokeWeight(2);

  // 创建波浪形状的岸边
  beginShape();
  for (var y = 0; y <= height; y += 5) {
    var offset = sin(y * 0.03 + frameCount * 0.02) * 8;
    vertex(shoreLine + offset, y);
  }
  endShape();
}

function drawTriggerZones() {
  noFill();
  strokeWeight(0.5);

  for (var i = 0; i < triggerZones.length; i++) {
    var zone = triggerZones[i];

    // 绘制区域边界
    stroke(zone.color[0], zone.color[1], zone.color[2], 80);
    line(0, zone.y, width, zone.y);

    // 如果区域激活，绘制高亮效果
    if (zone.active) {
      var progress = 1 - (millis() - zone.activeSince) / (zone.duration * 1000);
      if (progress > 0) {
        fill(zone.color[0], zone.color[1], zone.color[2], 60 * progress);
        noStroke();
        rect(shoreLine - 50, zone.y, 50, zone.height);
        noFill();
        stroke(zone.color[0], zone.color[1], zone.color[2], 120);
      } else {
        zone.active = false;
      }
    }

    // 绘制区域标签
    fill(200, 100);
    noStroke();
    textSize(12);
    text("P" + (i+1), 10, zone.y + zone.height/2 + 4);
  }
}

function updateActiveTriggers() {
  // 更新激活触发效果的持续时间
  for (var i = activeTriggers.length - 1; i >= 0; i--) {
    var trigger = activeTriggers[i];

    // 绘制柔和的触发效果
    fill(trigger.color[0], trigger.color[1], trigger.color[2], trigger.alpha);
    noStroke();
    ellipse(trigger.x, trigger.y, trigger.size);

    trigger.size += 0.3;
    trigger.alpha -= 1.5;

    if (trigger.alpha <= 0) {
      activeTriggers.splice(i, 1);
    }
  }
}

function Mobile(index) {
  this.index = index;
  this.velocity = createVector(0, 0);
  this.position0 = createVector(random(-100, width * 0.5), random(0, height));
  this.position = this.position0.copy();
  this.trans = random(80, 150); // 适中的透明度

  // 分配颜色 - 根据初始Y位置分配到10个区域之一
  this.zoneIndex = Math.floor((this.position.y / height) * 10);
  this.zoneIndex = constrain(this.zoneIndex, 0, 9);
  this.hu = colors[this.zoneIndex][0];
  this.sat = colors[this.zoneIndex][1];
  this.bri = colors[this.zoneIndex][2];

  this.size = random(1.5, 3); // 适中的粒子大小
  this.triggered = false; // 是否已触发
  this.baseSize = this.size; // 记录基础大小
  this.waveOffset = random(0, 100); // 波浪偏移量
}

Mobile.prototype.run = function() {
  this.update();
  this.display();
};

Mobile.prototype.update = function() {
  // 保存旧位置
  this.position0 = this.position.copy();

  // 基于噪声计算速度 - 创建流畅的波浪运动
  var timeFactor = frameCount * 0.01;
  var waveFactor = sin(timeFactor + this.waveOffset) * 0.5;

  var noiseX = noise(
    this.position.x * 0.005 + timeFactor,
    this.position.y * 0.005
  );

  var noiseY = noise(
    this.position.x * 0.005,
    this.position.y * 0.005 + timeFactor
  );

  this.velocity = createVector(
    (noiseX - 0.5) * 2,
    (noiseY - 0.5) * 2
  );

  this.velocity.mult(a5);

  // 增强向右（岸边方向）的流动趋势
  // 基础向右速度增加，确保粒子能够到达岸边
  var baseRightSpeed = 3.5; // 增加基础向右速度

  // 根据距离岸边的距离调整速度，距离越远速度越快
  var distToShore = shoreLine - this.position.x;
  var speedBoost = map(distToShore, 0, shoreLine, 0, 1.5);

  this.velocity.x += baseRightSpeed + speedBoost + waveFactor;
  this.velocity.y += sin(this.position.x * 0.02 + timeFactor) * 0.5;

  // 更新位置
  this.position.add(this.velocity);

  // 检查是否到达岸边界限
  if (!this.triggered && this.position.x >= shoreLine) {
    // 检查触发冷却时间和同时触发的颜色数量
    var currentTime = millis();
    var activeColorCount = countActiveColors();

    if (currentTime - lastTriggerTime > triggerCooldown && activeColorCount < 3) {
      this.trigger();
      lastTriggerTime = currentTime;
    } else {
      // 如果不能触发，反弹粒子
      this.position.x = shoreLine - 5;
      this.velocity.x *= -0.5;
    }
  }

  // 边界处理
  this.handleBoundaries();
};

function countActiveColors() {
  var count = 0;
  for (var i = 0; i < triggerZones.length; i++) {
    if (triggerZones[i].active) count++;
  }
  return count;
}

Mobile.prototype.trigger = function() {
  this.triggered = true;

  // 激活对应的触发区域
  triggerZones[this.zoneIndex].active = true;
  triggerZones[this.zoneIndex].activeSince = millis();
  triggerZones[this.zoneIndex].duration = random(0.8, 1.5); // 较短的持续时间

  // 添加柔和的激活效果
  activeTriggers.push({
    zoneIndex: this.zoneIndex,
    x: this.position.x,
    y: this.position.y,
    size: 8,
    alpha: 120,
    color: colors[this.zoneIndex]
  });

  // 重置粒子位置
  this.resetPosition();
};

Mobile.prototype.resetPosition = function() {
  this.position0 = createVector(random(-200, -50), random(0, height));
  this.position = this.position0.copy();
  this.triggered = false;
  this.waveOffset = random(0, 100); // 重置波浪偏移量
};

Mobile.prototype.handleBoundaries = function() {
  // 如果粒子完全离开右侧边界，重置位置
  if (this.position.x > width + 100) {
    this.resetPosition();
  }

  // 上下边界环绕
  if (this.position.y > height) {
    this.position.y = 0;
    this.position0.y = 0;
  } else if (this.position.y < 0) {
    this.position.y = height;
    this.position0.y = height;
  }
};

Mobile.prototype.display = function() {
  // 计算粒子大小 - 接近岸边时稍微变大
  var sizeMultiplier = 1;
  var distToShore = shoreLine - this.position.x;

  // 当接近岸边时稍微增大粒子
  if (distToShore < 100 && distToShore > 0) {
    sizeMultiplier = map(distToShore, 0, 100, 1.8, 1);
  }

  var currentSize = this.size * sizeMultiplier;

  // 绘制粒子轨迹线 - 使用较暗的颜色
  stroke(this.hu, this.sat * 0.7, this.bri * 0.7, this.trans * 0.5);
  line(this.position0.x, this.position0.y, this.position.x, this.position.y);

  // 在粒子当前位置绘制点 - 使用较亮的颜色
  fill(this.hu, this.sat, this.bri, this.trans);
  noStroke();
  ellipse(this.position.x, this.position.y, currentSize);

  // 如果非常接近岸边，绘制微弱的预警光环
  if (distToShore < 30 && distToShore > 0) {
    var proximity = 1 - (distToShore / 30);
    stroke(this.hu, this.sat, this.bri, 80 * proximity);
    noFill();
    ellipse(this.position.x, this.position.y, currentSize * 1.5 * proximity);
  }
};

function keyReleased() {
  if (key == "s" || key == "S") saveCanvas("WAVE_ART_" + day() + "_" + month() + "_" + hour() + "_" + minute() + "_" + second() + ".png");
  if (keyCode == 32) reset();
  if (key == "r" || key == "R") setup();
}

